  h.context.reduced=false;ValueAnimator.enabled=false;ValueAnimator.last=null;h.open();check(ValueAnimator.last==null,"system animator disable respected");h.root().getChildAt(2).performClick();h.menu.pause();h.catalog.moviesReady(true);check(h.changed==2,"paused request never changes home selection");
